from collections import defaultdict
def f(inp):
    from collections import defaultdict
    h,w=len(inp),len(inp[0])
    bg=max(max(r) for r in inp) if False else 2  # assume 2 background here
    by=defaultdict(list)
    for r in range(h):
        for c in range(w):
            if inp[r][c]!=2: by[inp[r][c]].append((r,c))
    out=[[2]*w for _ in range(h)]
    for pv,ps in by.items():
        rs=[a for a,b in ps]; cs=[b for a,b in ps]
        for r in range(min(rs),max(rs)+1):
            for c in range(min(cs),max(cs)+1):
                out[r][c]=pv
    return out
